plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
com.filesyncengine.desktop
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0
NSHighResolutionCapable
true

NSAppTransportSecurity

    NSAllowsLocalNetworking


NSHumanReadableCopyright
{{.Info.Copyright}}
SUFeedURL
https://github.com/bstone108/File-Sync-Engine/releases/latest/download/appcast-darwin-arm64.xml
SUPublicEDKey
dV+k5IynR3jrGAA7dbDmr66A2rrOH3vPbc45CVcuGUE=
SUEnableAutomaticChecks

SUScheduledCheckInterval
172800
SUAutomaticallyUpdate

SUAllowsAutomaticUpdates

{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.filesyncengine.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
